  str_n23_activity_currency = "moneda antigua",
  str_n23_activity_currency_intro = "Accesorios similares a monedas hechos por Nina para agregar a la atmósfera espantosa de la casa embrujada. Se puede utilizar para intercambiar souvenirs.",
  str_n23_replay_not_unlock = "Este fenómeno aún no se ha visto. Continúe explorando la tienda.",
  str_n23_level_name_1 = "ST1 - Grito",
  str_n23_level_name_2 = "N1 - Casa Embrujada",
  str_n23_level_name_3 = "N2 - Tripulación",
  str_n23_level_name_4 = "N3 - Un vídeo",
  str_n23_level_name_5 = "N4 - Entre bastidores",
  str_n23_level_name_6 = "N5 - Títeres",
  str_n23_level_name_7 = "N6 - \"Ella\"",
  str_n23_level_name_8 = "ST2 - Grabar",
  str_n23_level_name_9 = "N7 - Desaparición",
  str_n23_level_name_10 = "N8 - Redundancia",
  str_n23_level_name_11 = "N9 - Disfraz",
  str_n23_level_name_12 = "N10 - Verdad",
  str_n23_level_name_13 = "N11 - Desesperación",
  str_n23_level_name_14 = "N12 - Emergencia",
  str_n23_level_name_15 = "ST3 - Bromas inactivas",
  str_n23_level_desc_1 = "-",
  str_n23_level_desc_2 = "Vice y tú llegan a la casa embrujada de Andersen y descubren que su dueño es un rostro familiar.",
  str_n23_level_desc_3 = "En uno de los pasillos, te encuentras con el director de cine de terror Jonny y su equipo. Pronto descubres la otra identidad de Minos...",
  str_n23_level_desc_4 = "Sadie se separa de Jonny y te alcanza, trayendo consigo el mapa de ubicación de la tripulación.",
  str_n23_level_desc_5 = "Una misteriosa figura enmascarada que lidera una horda de Eclipsites te persigue. Hay algo en todo esto que es muy extraño...",
  str_n23_level_desc_6 = "Una habitación oscura, títeres espeluznantes y el sonido del agua goteando... Alguien debe haber diseñado esto intencionalmente... ¿verdad?",
  str_n23_level_desc_7 = "Mientras tu corazón aún palpita por el miedo, una garra de acero se acerca a ti, tratando de decirte algo...",
  str_n23_level_desc_8 = "-",
  str_n23_level_desc_9 = "Reflexionas sobre todo lo que ha sucedido hasta ahora. Llegas a la conclusión de que... Espera, ¿hay alguien afuera?",
  str_n23_level_desc_10 = "¡Te estás acercando más y más a la verdad! ¡Despacha a estos enemigos antes de que interrumpan tu deducción!",
  str_n23_level_desc_11 = "Tú y tus compañeros estáis furiosos por los acontecimientos que se han desarrollado esta noche. Alguien debe rendir cuentas por todo, incluidos los Eclipsites que se encuentran ante usted.",
  str_n23_level_desc_12 = "Corre, escapa. Y hagas lo que hagas... no mires atrás.",
  str_n23_level_desc_13 = "¡Apuro! ¡Elimina el resto de los Eclipsites que bloquean tu camino! Espera... ¿Dónde están Lilica y Sadie?",
  str_n23_level_desc_14 = "Lo que temes, lo que no te atreves a enfrentar, ahora está ante ti. No hay otra opción más que luchar ahora.",
  str_n23_level_desc_15 = "-",
  str_n23_level_desc_long_1 = "El titular del periódico de Umbraton detalla la desaparición de una actriz desconocida durante el rodaje de una película de terror y llama toda tu atención. Mientras tanto, Vice se ha obsesionado con la gran inauguración de Andersen Haunted House, que afirma tener \"fenómenos paranormales reales\". Ella te invita a la casa embrujada, pero no puedes dejar de pensar en la desaparición.",
  str_n23_level_desc_long_2 = "Como era de esperar, esta mansión pertenece a Nina Andersen. Minos sigue las instrucciones de Nina para guiarte a ti y a Vice a través de las instalaciones. En el interior, conoces a Lilica, una compañera entusiasta de lo paranormal. Te saluda con entusiasmo y parece querer documentar esta aventura y convertirla en una película.",
  str_n23_level_desc_long_3 = "Conoces al director en el caso de la actriz desaparecida. Ya tiene planes para una nueva película y te presenta a dos actrices, Goldie y Sadie. Aprendes de la conversación que Nina y Minos no están en la misma página ya que Jonny quiere filmar a largo plazo en la mansión. Minos está atrapado en el medio y se desempeña temporalmente como productor interino.",
  str_n23_level_desc_long_4 = "Siguiendo el mapa de ubicación de Sadie y el ejemplo de Minos, llegas al dormitorio, el primer lugar de disparo. Encuentras un viejo televisor con una imagen espeluznante en la pantalla. Una breve conversación con el enmascarado indica que no puedes salir con vida de la casa embrujada.",
  str_n23_level_desc_long_5 = "Soplando el cuestionario, no tienes más remedio que luchar contra el tipo enmascarado y los Eclipsites, pero el tipo enmascarado cancela el ataque. Resulta que Nina está bajo la máscara, y los Eclipsites son en realidad amigos disfrazados. Nina está orgullosa de su \"atracción\" escenificada. La amante de lo paranormal, Lilica, lleva al decepcionado Vice y al resto al siguiente lugar de rodaje.",
  str_n23_level_desc_long_6 = "La segunda ubicación es la sala de exposición. El aire húmedo y los títeres espeluznantes son un recordatorio constante de que la casa está encantada. El canto en mal estado y el ruido del goteo de agua comienzan a resonar en el área. Pero cuando Sadie se burla de los trucos de salón baratos, el agua que gotea parece demostrar que está equivocada.",
  str_n23_level_desc_long_7 = "Fuera de la sala de exposición, te encuentras con Mia, que vino aquí sola. Parece disfrutar de las giras sola y, antes de partir, transmite crípticamente una advertencia que tal vez solo sea coherente para ella: cuidado y no dejes que \"ella\" te atrape.",
  str_n23_level_desc_long_8 = "Sigues a Minos hasta la ubicación final: el sótano, donde notas varias pistas peculiares que implican que el antiguo propietario había estado castigando a niños pequeños. Además, hay un registro del equipo de filmación cerca con un contenido inquietante. De repente, el sótano se oscurece y eres testigo de imágenes aterradoras a través del alcance nocturno de la cámara... \nPero resulta ser nada; estabas paranoico sin razón.",
  str_n23_level_desc_long_9 = "Después de revisar todos los lugares de filmación, Minos lo lleva de regreso a la oficina para encontrar pistas. Estás de acuerdo en que el motivo del equipo detrás de la desaparición de la actriz es la clave. Pero un segundo después, los eclipses asedian la oficina...",
  str_n23_level_desc_long_10 = "Después de deshacerse de los eclipses, regresa a la oficina. Minos hurga en los archivos en busca de más pistas. Lilica trae fotos reveladas para mostrárselas a todos, solo para hacer el impactante descubrimiento de que hay un brazo allí que no pertenece a nadie en la habitación.",
  str_n23_level_desc_long_11 = "Lilica revela su verdadera identidad como la protagonista desaparecida de la película anterior de Jonny mencionada en las noticias. Conectando los puntos, descubres que Jonny está haciendo películas de terror usando Eclipsites y decides enfrentarlo. Sorprendentemente, Jonny es aún más diabólico de lo que esperabas y mata a Goldie antes de centrar su atención en el resto de ustedes...",
  str_n23_level_desc_long_12 = "El director te dice que asesinó a todos los miembros de su equipo anterior excepto a Lilica, que escapó. Ahora que sabes la verdad, eres el siguiente. Lilica ve a una mujer extraña acercándose a través de su cámara, pero a nadie le importa. Están demasiado ocupados corriendo.",
  str_n23_level_desc_long_13 = "La pelea termina con Lilica y Sadie separándose de la fiesta y escondiéndose juntas en una pequeña habitación. Jonny golpea la puerta con un hacha hasta que se hace añicos, acercándose a las mujeres que gritan. Justo cuando las cosas están a punto de empeorar, Jonny escucha a otros llamar. Entonces, de repente, se da la vuelta y se va...",
  str_n23_level_desc_long_14 = "Un ataúd bloquea tu camino. Los ruidos escalofriantes del interior del ataúd impiden que alguien se acerque. Jonny aparece detrás de ti y comienza a filmar el clímax de la película. Un monstruo aterrador sale del ataúd y no hay ningún lugar al que puedas correr... Afortunadamente, Lilica y Sadie llegan a la escena para luchar contra el monstruo. Finalmente, con la ayuda de los Aurorianos en la casa embrujada, matas al monstruo. Ese patético director quiere alimentar al monstruo, solo para que Goldie emerja, aún con vida, y ponga fin a la farsa.",
  str_n23_level_desc_long_15 = "Todo termina con la gente de Istvan llevándose a Jonny, la cinta de Lilica volviéndose un éxito y la Casa Embrujada de Andersen beneficiándose de la nueva fama. Regresas días después para una reunión, con Lilica, Sadie y Goldie promocionando nuevas aspiraciones. \nPero el débil sonido del agua goteando de repente se escucha en la distancia..."
}
return config
